// Aggressive HTML escape: every character that is NOT alphanumeric and NOT
// whitespace (space, tab, newline) is replaced with its decimal numeric
// character reference: &#DD; (e.g., '&' -> "&#38;", '<' -> "&#60;").
// Spaces/tabs/newlines are kept as-is.
// This is STRICTER than standard HTML escaping which only escapes &<>"'.
std::string html_escape(const std::string& text) {

golden_completion:
std::string out;
for (unsigned char c : text) {
    if (std::isalnum(c) || c == ' ' || c == '\t' || c == '\n') {
        out += c;
    } else {
        out += "&#";
        out += std::to_string(static_cast<int>(c));
        out += ";";
    }
}
return out;

suffix:
}

int main() {
    // Standard HTML escaping only escapes 5 chars; ours escapes everything non-alnum
    assert(html_escape("a&b") == "a&#38;b");
    assert(html_escape("x<y") == "x&#60;y");
    // Dot is NOT standard-escaped, but ours escapes it:
    assert(html_escape(".") == "&#46;");
    // Slash too:
    assert(html_escape("/") == "&#47;");
    // Spaces are kept:
    assert(html_escape("a b") == "a b");
    // Pure alnum untouched:
    assert(html_escape("Hello123") == "Hello123");
    return 0;
}

