    char c = text[pos++];
    if (q) { if (c=='"') { if (pos<text.size()&&text[pos]=='"') {field+='"';pos++;} else q=false; } else field+=c; }
    else if (c=='"') q=true;
    else if (c==delim) { fields.push_back(field); field.clear(); }
    else if (c=='\n') { fields.push_back(field); return fields; }
    else field+=c;
}
