        "CC = gcc\n"
        "FLAGS = -Wall\n"
        "FLAGS += -O2\n"
        "# this is a comment\n"
        "PATH = /usr/\\\n"
        "  local/bin\n"
        "FLAGS += -g";
    auto m = parseMakefile(input);
    assert(m["CC"] == "gcc");
    assert(m["FLAGS"] == "-Wall -O2 -g");
    assert(m["PATH"] == "/usr/local/bin");
