// Dockerfile ENV parser:
// ENV key=value key2=value2 ...  (multi-key, quoted values ok)
// ENV key value                  (single-key, rest is value)
// Backslash continuation, # comments, non-ENV ignored.

std::string strip(const std::string& s) {
    size_t a = s.find_first_not_of(" \t\r");
    if (a == std::string::npos) return "";
    return s.substr(a, s.find_last_not_of(" \t\r") - a + 1);
}

bool has_eq_outside_quotes(const std::string& s) {
    for (size_t i = 0; i < s.size(); i++) {
        if (s[i]=='"') { while (++i<s.size()&&s[i]!='"'); continue; }
        if (s[i]=='=') return true;
    }
    return false;
}

void parse_multi_kv(const std::string& rest, std::map<std::string,std::string>& result) {
    size_t i = 0;
    while (i < rest.size()) {
        while (i<rest.size()&&(rest[i]==' '||rest[i]=='\t')) i++;
        size_t ke = rest.find('=', i); if (ke==std::string::npos) break;
        std::string key=rest.substr(i,ke-i); i=ke+1; std::string val;
        if (i<rest.size()&&rest[i]=='"') {
            i++; while (i<rest.size()&&rest[i]!='"') val+=rest[i++]; if (i<rest.size()) i++;
        } else { while (i<rest.size()&&rest[i]!=' '&&rest[i]!='\t') val+=rest[i++]; }
        result[key] = val;
    }
}

std::map<std::string, std::string> parse_dockerfile_env(const std::string& text) {
    std::map<std::string, std::string> result;
    std::istringstream iss(text); std::string raw;

